sys_ux_client_script.script:
/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
* @param {any} params.imports
* @param {ApiHelpers} params.helpers
*/
function handler({api, event, helpers, imports}) {
    console.debug(">>> Employee - Enter:", event);

    /**
     * アイテムを一覧から選択後している場合は、何もしない
     */
    // event.payload選択したイベントがトリガーされたときにコンポーネントによって送信されるデータ
    if (event.payload.actionSource == "select") {
        console.debug(">>>> action=select exit.");
        event.context.item.value.employee.action = "select";

        api.setState("queryAffiliation", "");
        api.setState("queryGaudi", "");
        api.setState("inputValue", "");
        api.data.look_up_user.refresh();
        api.data.look_up_affiliation.refresh();
        return;
    }

    event.context.item.value.employee.action = "input";
    event.context.item.value.employee.selected = false;
    // const txt = event.payload.value.trim() || '';
    // const txt = api.state.inputValue;
    /**
     * table: u_z1_gaudi_rysids
     * query: u_rysidSTARTSWITHshiba^u_name_jaSTARTSWITH芝^u_affi_nameSTARTSWITHベニック
     */
    // const query = txt ? `u_rysidSTARTSWITH${txt}^ORu_name_jaSTARTSWITH${txt}^ORu_affi_nameSTARTSWITH${txt}^ORu_empnumSTARTSWITH${txt}` : '';
    // api.setState("queryGaudi", query);
    // api.setState("listGaudi", []);
    // console.debug(">>>query="+query);


    // Data Sourceは自動にしているけど、refresh()しないと入力値での検索しない
    api.data.look_up_user.refresh();
    api.data.look_up_affiliation.refresh();
}
